-- Blyth Cabin QITP seed. Attaches to the EXISTING Blyth project (resolved by
-- code '26004' at apply time — does NOT create a project). 6 ordered sections
-- with per-item checklists + HOLD points, verbatim from Cabin_QITP.html; 140
-- cabins with stable QR tokens (from the 26004 register). Idempotent (INSERT OR
-- IGNORE). Requires a project with code '26004' to exist.
INSERT OR IGNORE INTO qitp_sections (project_id, seq, title, point_type, items, created_at) VALUES ((SELECT id FROM projects WHERE code='26004'),1,'Pre-Strip Survey & Isolation','HOLD','["Cabin ID confirmed and matches register / drawing", "Photographic condition survey of all elevations complete", "Existing defects / damage logged with photos", "Power & lighting isolation by Durata confirmed", "Access (MEWP/scaffold) in place; task RAMS briefed to operatives", "HOLD: Joint pre-strip condition survey agreed with Durata"]','2026-06-26T00:00:00.000Z');
INSERT OR IGNORE INTO qitp_sections (project_id, seq, title, point_type, items, created_at) VALUES ((SELECT id FROM projects WHERE code='26004'),2,'Strip-Out (Flashings, Gutters, Downpipes)',NULL,'["Flashings removed and labelled to this cabin ID", "Gutters removed and set aside / labelled", "Downpipes removed", "Fixings retained, bagged and labelled to cabin", "Exposed roof / openings made weathertight after strip", "No damage to cabin envelope (photo evidence)"]','2026-06-26T00:00:00.000Z');
INSERT OR IGNORE INTO qitp_sections (project_id, seq, title, point_type, items, created_at) VALUES ((SELECT id FROM projects WHERE code='26004'),3,'Wrap, Lift & Transport',NULL,'["Cabin wrapped / protected for move", "Lifting points checked; certified lift plan in place", "Lift completed without damage", "Transport to laydown / storage complete", "Condition on arrival recorded (photo)"]','2026-06-26T00:00:00.000Z');
INSERT OR IGNORE INTO qitp_sections (project_id, seq, title, point_type, items, created_at) VALUES ((SELECT id FROM projects WHERE code='26004'),4,'Storage / Receipt','HOLD','["Storage location / bay recorded against cabin ID", "Set down level and packed / supported correctly", "Weather protection in place", "Condition while stored checked (no ingress / damage)", "HOLD: Ready-to-reinstall confirmation before lift back"]','2026-06-26T00:00:00.000Z');
INSERT OR IGNORE INTO qitp_sections (project_id, seq, title, point_type, items, created_at) VALUES ((SELECT id FROM projects WHERE code='26004'),5,'Re-site & Reinstall','HOLD','["HOLD: Foundations / base ready and level checked (critical gate)", "Cabin positioned and levelled to setting-out", "Links / inter-cabin connections made", "Flashings reinstalled (correct cabin set)", "Gutters reinstalled and falls checked", "Downpipes reinstalled and connected to drainage", "Weathertightness / water test completed"]','2026-06-26T00:00:00.000Z');
INSERT OR IGNORE INTO qitp_sections (project_id, seq, title, point_type, items, created_at) VALUES ((SELECT id FROM projects WHERE code='26004'),6,'Final Inspection & Handover','HOLD','["Snagging complete; defects closed out", "As-built / completion photos taken", "QA records for this cabin complete", "HOLD: Client (Durata) sign-off obtained", "Handover accepted"]','2026-06-26T00:00:00.000Z');
